import{_ as i,l,o as e,c as d,v as n,p as r,x as o,d as c,i as s,S as m}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"符号与 mangling","description":"","frontmatter":{"title":"符号与 mangling","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/name-mangling.md","filePath":"cs/name-mangling.md","lastUpdated":1789023840000}'),g={name:"cs/name-mangling.md"};function p(_,a,h,u,A,f){const t=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=n('<h1 id="符号与-mangling" tabindex="-1">符号与 mangling <a class="header-anchor" href="#符号与-mangling" aria-label="Permalink to &quot;符号与 mangling&quot;">​</a></h1><div class="epigraph"><p>链接器只认字节串名字。C++ 的重载、命名空间、模板要编进一个符号：mangling。调试与 `dlsym` 必须能来回译。</p><footer>—— 据 Itanium C++ ABI 名字改编；System V ABI 符号绑定；龙书链接章整理</footer></div><p>上一课<a href="/cs/dwarf-debug-info">DWARF</a> 里 DIE 有源名。缺口是<strong>目标文件符号表</strong>的名字：C 的 <code>foo</code> 常就是 <code>foo</code>；C++ 是 <code>_Z...</code>。本课钉 mangling 与链接属性（<code>static</code>、weak、visibility），下一课序从解析归档开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个 <code>void f(int)</code> / <code>void f(double)</code> 不能同名符号。mangling 把类型签名编进去。模板实例：再编模板实参。缺口是<strong>编码规则与互操作</strong>，不是行号表。</p><p><code>extern &quot;C&quot;</code> 关闭 mangling，才能与 C 库链接。Rust/Swift 各有方案，点名。</p><h3 id="mangling-不是卫生宏" tabindex="-1">mangling 不是卫生宏 <a class="header-anchor" href="#mangling-不是卫生宏" aria-label="Permalink to &quot;mangling 不是卫生宏&quot;">​</a></h3><p>宏改源名绑定；mangling 是 ABI 层唯一化。α 换名在编译器内部 IR，符号是对外的。</p><p><span class="marginnote">Itanium C++ ABI。MSVC 用另一套。<code>c++filt</code> demangle。本课以 Itanium 为默认 Unix。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端为每个带链接的实体发 mangled 名。局部符号（<code>static</code>）可内部链接，LTO 仍可改名。弱符号：内联、模板在多个 TU 定义，链接器留一份。</p>',11)),(e(),r(m,null,{default:o(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E8%AF%AD%E8%A8%80%E5%AE%9E%E4%BD%93%22%5D%20--%3E%20MANG%5B%22mangled%20%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20MANG%20--%3E%20OBJ%5B%22.o%20%E7%AC%A6%E5%8F%B7%E8%A1%A8%22%5D%0A%20%20OBJ%20--%3E%20LD%5B%22%E9%93%BE%E6%8E%A5%E5%99%A8%E8%A7%A3%E6%9E%90%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>与 DWARF：<code>DW_AT_linkage_name</code> 存 mangled，<code>DW_AT_name</code> 存源名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ABI 不稳：改 mangling = 不能与旧 <code>.o</code> 链接。不要手写猜测的 <code>_Z</code> 串去 <code>dlsym</code>，用 <code>extern &quot;C&quot;</code> 或官方工具。</p><p>过长符号：模板错误信息膨胀；编译器可截断哈希（谨慎）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写链接器解析算法全文。后课默认：C++ 符号是 mangled 串。下一课链接器符号解析与归档。</p><p>也不把 mangling 当混淆器（那是另一层 strip/obfuscate）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链接名是扁平字符串；C++ 用 ABI mangling 编码签名。</li><li><code>extern &quot;C&quot;</code> 与 C 互链；弱符号服务模板。</li><li>调试信息同时保留源名与链接名。</li><li>出处：Itanium C++ ABI；System V ABI；龙书链接。</li></ul>',9))])}const B=i(g,[["render",p]]);export{C as __pageData,B as default};
